func newFiscalYear() unsafe.Pointer { return unsafe.Pointer(new(fiscalyear.FiscalYear)) }

func newNFiscalYear(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fiscalyear.FiscalYear, n)))
}

func ptrFiscalYear(p unsafe.Pointer, c int32) any {
	r := (*fiscalyear.FiscalYear)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Status))
	case 4:
		return (*int64)(unsafe.Pointer(&r.Year))
	case 5:
		return &r.Name
	case 6:
		return &r.Description
	case 7:
		return &r.StartDate
	case 8:
		return &r.EndDate
	case 9:
		return &r.IsCurrent
	case 10:
		return &r.IsCalendarYear
	case 11:
		return &r.AllowAdjustingEntries
	case 12:
		return &r.ClosedAt
	case 13:
		return (*string)(unsafe.Pointer(&r.ClosedByID))
	case 14:
		return &r.LockedAt
	case 15:
		return (*string)(unsafe.Pointer(&r.LockedByID))
	case 16:
		return &r.ReopenedAt
	case 17:
		return (*string)(unsafe.Pointer(&r.ReopenedByID))
	case 18:
		return &r.ReopenReason
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	case 22:
		return &r.SearchVector
	case 23:
		return &r.Rank
	}
	return nil
}

func valueFiscalYear(p unsafe.Pointer, c int32) any {
	r := (*fiscalyear.FiscalYear)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Status)
	case 4:
		return int64(r.Year)
	case 5:
		return r.Name
	case 6:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 7:
		return r.StartDate
	case 8:
		return r.EndDate
	case 9:
		return r.IsCurrent
	case 10:
		return r.IsCalendarYear
	case 11:
		return r.AllowAdjustingEntries
	case 12:
		if r.ClosedAt == nil {
			return nil
		}
		return *r.ClosedAt
	case 13:
		if r.ClosedByID == "" {
			return nil
		}
		return string(r.ClosedByID)
	case 14:
		if r.LockedAt == nil {
			return nil
		}
		return *r.LockedAt
	case 15:
		if r.LockedByID == "" {
			return nil
		}
		return string(r.LockedByID)
	case 16:
		if r.ReopenedAt == nil {
			return nil
		}
		return *r.ReopenedAt
	case 17:
		if r.ReopenedByID == "" {
			return nil
		}
		return string(r.ReopenedByID)
	case 18:
		if r.ReopenReason == "" {
			return nil
		}
		return r.ReopenReason
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	case 22:
		return r.SearchVector
	case 23:
		return r.Rank
	}
	return nil
}

func attachFiscalYear(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fiscalyear.FiscalYear)(p)
	switch rel {
	case 0:
		r.ClosedBy = (*tenant.User)(child)
	case 1:
		r.LockedBy = (*tenant.User)(child)
	case 2:
		r.ReopenedBy = (*tenant.User)(child)
	case 3:
		r.Periods = append(r.Periods, (*fiscalperiod.FiscalPeriod)(child))
	}
}

func beforeCreateFiscalYear(ctx context.Context, p unsafe.Pointer) error {
	return (*fiscalyear.FiscalYear)(p).BeforeCreate(ctx)
}

